typedef unsigned int nslSourceId;
typedef unsigned int nlUint32;

typedef enum _nslSoundParamEnum
{
  NSL_SOUNDPARAM_VOLUME,
  NSL_SOUNDPARAM_PITCH,
  NSL_SOUNDPARAM_MINDIST,
  NSL_SOUNDPARAM_MAXDIST,
  NSL_SOUNDPARAM_Z
} nslSoundParamEnum;

struct nslSource
{
  char prefix[0x3c];
  nslSourceId myId;
  char middle[0x0c];
  nlUint32 gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem
{
  char listenerPo[0x40];
  nslSource sourceSlots[512];
  char afterSources[0x9810];
  int initialized;
  char beforeOn[0x2c];
  bool on;
};

extern nslSystem nsl;
extern void nslFatal(const char *, ...);
__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nslFatal__FPCce, 0x00391420");

#define NSL_INVALID_ID 0
#define NSL_NUM_SOURCES 512
#define NSL_SOURCE_ID_MASK 0xFFFF0000
#define NSL_SOURCE_SLOT_MASK 0x0000FFFF
#define NSL_GET_SOURCE_SLOT_FROM_ID( x ) ( x&NSL_SOURCE_SLOT_MASK )

inline void _nslCheckSourceIdValidity(nslSourceId checkId)
{
  nslSourceId checkSlot = (checkId & NSL_SOURCE_SLOT_MASK);
  nslSourceId upCheckId = (checkId & NSL_SOURCE_ID_MASK);
  nlUint32 gasId = nsl.sourceSlots[checkSlot].gasSourceId;

  nlUint32 negativeOne = (nlUint32)-1;
  if (!(checkId != NSL_INVALID_ID))
  {
    nslFatal("This source id is the INVALID id");
  }
  if (!(gasId != negativeOne))
  {
    nslFatal("This source has a bad GAS id");
  }
  if (!(checkSlot < NSL_NUM_SOURCES))
  {
    nslFatal("This source is above the max number of sources");
  }
  if (!(checkId == nsl.sourceSlots[checkSlot].myId))
  {
    nslFatal("This ID passed does not match the id for the source slot");
  }
  if (!(upCheckId > 0))
  {
    nslFatal("THE INSTANCE PART OF THE ID IS NOT > 0");
  }
  if (checkSlot > NSL_NUM_SOURCES)
  {
    nslFatal("THE SLOT PART IS MORE THAN THE NUMBER OF TOTAL SLOTS");
  }
  return;
}

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal("NSL NOT INITIALIZED");
}

#define ASSERT_SOURCE_ID_VALID(checkId) _nslCheckSourceIdValidity(checkId)
#define ASSERT_NSL_INITIALIZED() _nslInitialized()

float nslGetSourceParam( nslSourceId whichSource, nslSoundParamEnum whichParam )
{
  if (!nsl.on) return 0.0;
  ASSERT_NSL_INITIALIZED();
  ASSERT_SOURCE_ID_VALID(whichSource);
  switch (whichParam) {
    case NSL_SOUNDPARAM_VOLUME: 
      return nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(whichSource)].rawVolume; break;
    case NSL_SOUNDPARAM_PITCH:
      return nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(whichSource)].pitch; break;
    case NSL_SOUNDPARAM_MINDIST:
      return nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(whichSource)].minDist; break;
    case NSL_SOUNDPARAM_MAXDIST:
      return nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(whichSource)].maxDist; break;
    default: nslFatal(false && "Unhandled sourcetype"); break;
  }

  return 0.0f;
}
